import hashlib, json, os

def make_checksum(pkg_dir, crate_sha):
    files = {}
    for root, _dirs, names in os.walk(pkg_dir):
        for n in names:
            if n == ".cargo-checksum.json":
                continue
            p = os.path.join(root, n)
            rel = os.path.relpath(p, pkg_dir)
            files[rel] = hashlib.sha256(open(p, "rb").read()).hexdigest()
    with open(os.path.join(pkg_dir, ".cargo-checksum.json"), "w") as f:
        json.dump({"files": files, "package": crate_sha}, f, indent=1, sort_keys=True)

